tool_calls.arguments:
{"command": "for d in $WORKSPACE_DIR/documents/matters/*/; do dir=$(basename $d); has_antitrust=0; has_hsr=0; 
if ls "$d"*/Antitrust* 2>/dev/null | grep -q .; then has_antitrust=1; fi
if ls "$d"*/HSR* 2>/dev/null | grep -q .; then has_hsr=1; fi
if ls "$d"*/"Antitrust & Regulatory"* 2>/dev/null | grep -q .; then has_antitrust=1; fi
echo "$dir: antitrust=$has_antitrust hsr=$has_hsr"; done"}

